script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		modalId: "[component-id$='inbound_integration_type_selection_modal']",
		headerLabel: null,
		showModal: true,
		preserveState: false,
		displayOptions: {
		customSize: {
			height: "750px" ,
			width: "800px" 
		} 
	},
		bare: false,
		viewportElementId: null,
		viewportRoute: null,
		viewportFields: null,
		viewportParams: null
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const inboundGrantTypeToEditPageLink = {
        "ropc": "ropc-record",
        "client_credential": "client-credential-record",
        "oidc": "oidc-record",
        "jwt": "jwt-bearer-record",
        "authz_code": "authz-code-record",
    };
    let sysId = event.payload.context.row.key;
    let grantType = event.payload.context.row.cells.inbound_grant_type.value;
    let legacyMode = false;
    if (!inboundGrantTypeToEditPageLink[grantType]) {
        legacyMode = true;
    }
    return {
        route: legacyMode ? null : inboundGrantTypeToEditPageLink[grantType],
        fields: legacyMode ? null : {
            "recordId": sysId,
            timestamp: Date.now()
        },
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: legacyMode ? {
            url: "oauth_entity.do?sys_id=" + sysId
        } : null
    };

}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	if(event.payload.cell.metadata.recordClassName == 'sys_user'){
		return {
			external: {url: event.payload.cell.href}
		};
	}
})

